    g.Update();
    CHECK(g.Attacks == 3 && g.Strafes == 1 && g.Terminations == 1);
    CHECK(cm.LastCreature == &me && cm.LastTarget == &enemy);
    CHECK(g_log == "current;msg;register;look;move;ready;strafe;attack;move;ready;attack;move;ready;attack;T;");

